11 | // survives a fresh clone (spec §9, cli-spec §13). Advisory-only behaviour is
12 | // enforced inside scan --context pre-commit, not in the hook script.
13 | func installHook(root string) error {
14 | 	hooks := filepath.Join(root, ".cavet", "hooks")
15 | 	if err := os.MkdirAll(hooks, 0o755); err != nil {
16 | 		return err
17 | 	}
18 | 	shim := "#!/bin/sh\nexec cavet scan --staged --context pre-commit\n"
19 | 	if err := os.WriteFile(filepath.Join(hooks, "pre-commit"), []byte(shim), 0o755); err != nil {
20 | 		return err
21 | 	}

